/* @lc app=leetcode id=2699 lang=kotlin */ class Solution { fun dj(n: Int, e: Array<IntArray>, w: IntArray, s: Int): LongArray = e.indices.flatMap { i -> listOf(e[i][0] to (e[i][1] to w[i]), e[i][1] to (e[i][0] to w[i])) }.groupBy({ it.first }, { it.second }).let { g -> LongArray(n) { Long.MAX_VALUE / 4 }.also { it[s] = 0 }.let { d -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to s) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().filter { (v, x) -> c + x < d[v] }.forEach { (v, x) -> pq.add(c + x to v).also { d[v] = c + x } } }.let { d } } } } fun modifiedGraphEdges(n: Int, edges: Array<IntArray>, source: Int, destination: Int, target: Int): Array<IntArray> = IntArray(edges.size) { if (edges[it][2] == -1) 1 else edges[it][2] }.let { w -> edges.indices.filter { edges[it][2] == -1 }.fold(dj(n, edges, w, source)[destination]) { cur, i -> if (cur >= target) cur else w.also { it[i] += (target - cur).toInt() }.let { dj(n, edges, w, source)[destination] } }.let { fin -> if (fin == target.toLong()) Array(edges.size) { intArrayOf(edges[it][0], edges[it][1], w[it]) } else arrayOf() } } }